package test;

import java.util.Arrays;

public class TestClass {
    public void comparePrimitivesAndStrings() {
        char c1 = 'a';
        char c2 = 'b';
        if (c1 == c2) { // Should NOT match, primitive char comparison
            System.out.println("Equal chars");
        }

        String s1 = "hello";
        String s2 = "world";
        if (s1 == s2) { // Should NOT match, String reference comparison (different semantics for equals)
            System.out.println("Equal strings by reference");
        }

        int[] arr1 = {1, 2};
        int[] arr2 = {1, 2};
        if (arr1 == arr2) { // Should NOT match, type is int[] not char[]
            System.out.println("Equal int arrays by reference");
        }
    }
}
